import{_ as t,o as a,c as o,ah as i}from"./chunks/framework.DDXs_i7t.js";const m=JSON.parse('{"title":"Logbook: Justice at Peršmanhof – A Victory Against the Hydra","description":"","frontmatter":{},"headers":[],"relativePath":"en/logbuch/2026-04-16-persmanhof-victory.md","filePath":"en/logbuch/2026-04-16-persmanhof-victory.md"}'),r={name:"en/logbuch/2026-04-16-persmanhof-victory.md"};function n(s,e,h,c,l,u){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="logbook-justice-at-persmanhof-–-a-victory-against-the-hydra" tabindex="-1">Logbook: Justice at Peršmanhof – A Victory Against the Hydra <a class="header-anchor" href="#logbook-justice-at-persmanhof-–-a-victory-against-the-hydra" aria-label="Permalink to &quot;Logbook: Justice at Peršmanhof – A Victory Against the Hydra&quot;">​</a></h1><p><strong>Date:</strong> April 16, 2026 <strong>Status:</strong> International Landmark for the Rule of Law</p><h2 id="🏛️-today-s-court-ruling" tabindex="-1">🏛️ Today&#39;s Court Ruling <a class="header-anchor" href="#🏛️-today-s-court-ruling" aria-label="Permalink to &quot;🏛️ Today&#39;s Court Ruling&quot;">​</a></h2><p>The Carinthian Administrative Court has officially ruled that the identity checks carried out by the police at the Peršmanhof memorial site in July 2025 were <strong>unlawful</strong>. This is a massive blow to the state security services (LSE), which used the pretense of &quot;illegal camping&quot; and nature conservation to harass an anti-fascist youth camp.</p><h2 id="🔗-the-continuity-of-repression" tabindex="-1">🔗 The Continuity of Repression <a class="header-anchor" href="#🔗-the-continuity-of-repression" aria-label="Permalink to &quot;🔗 The Continuity of Repression&quot;">​</a></h2><p>In our project &quot;The Horten Mystery,&quot; the Peršmanhof case serves as a chilling example of the <strong>Hydra of Power</strong>:</p><ol><li><strong>1945:</strong> The SS/Gestapo massacre of the Sadovnik family (11 victims, including 7 children).</li><li><strong>2025:</strong> A massive &quot;state security&quot; operation involving helicopters, drones, and heavily armed units targeting those who remember.</li><li><strong>The FPÖ Angle:</strong> The Freedom Party (FPÖ), the successor organization to post-war structures that sheltered former Nazis, has actively defended the police raid. Their dismissal of the camp as &quot;left-wing extremism&quot; is a direct ideological echo of the repression faced by the Slovenian resistance 80 years ago.</li></ol><h2 id="⚖️-the-double-standard" tabindex="-1">⚖️ The Double Standard <a class="header-anchor" href="#⚖️-the-double-standard" aria-label="Permalink to &quot;⚖️ The Double Standard&quot;">​</a></h2><p>The contrast is sharp and central to our narrative:</p><ul><li><strong>In Linz:</strong> High-ranking politicians like August Wöginger defend &quot;interventions&quot; in job appointments as &quot;proximity to citizens&quot; (Bürgernähe).</li><li><strong>At Peršmanhof:</strong> Peaceful remembrance is met with military-grade police force under the guise of &quot;minor administrative violations.&quot;</li></ul><h2 id="💬-public-reaction" tabindex="-1">💬 Public Reaction <a class="header-anchor" href="#💬-public-reaction" aria-label="Permalink to &quot;💬 Public Reaction&quot;">​</a></h2><p>The forum at <em>Der Standard</em> is boiling over. Citizens are decrying the &quot;Banana Republic&quot; tactics used to intimidate minorities and activists. The court has now confirmed what the people knew: the Hydra showed its heads at Peršmanhof, but today, the law has cut them down.</p><p><strong>Project Integration:</strong> Our script (Part 4) now includes the scene &quot;The Echo of Peršmanhof,&quot; bridging the gap between historical atrocities and modern-day systemic abuse.</p><p>#Peršmanhof #Justice #RuleOfLaw #HydraOfPower #HortenMystery #AntiFascism #HumanRights</p>',14)])])}const g=t(r,[["render",n]]);export{m as __pageData,g as default};
